40	// 逻辑Event：封装多个物理 ccu::Event，提供超过16位的信号空间。
41	// 算法侧按逻辑 signalIdx (0..N-1) 进行 Record/Wait，内部自动处理 event 分组与 mask 计算。
42	class CcuEventGroup {
43	public:
44	    CcuEventGroup() = default;
45	
46	    // 按逻辑信号数初始化内部 event 向量
47	    void Init(uint32_t signalCount)
48	    {
49	        signalCount_ = signalCount;
50	        uint32_t eventNum = (signalCount + EVENT_BIT_WIDTH - 1) / EVENT_BIT_WIDTH;
51	        events_.resize(eventNum);
52	    }
53	
54	    // ---- Post 路径：给 ccu::Write/Read/LocalCopy 传参使用 ----
55	    ccu::Event& GetEvent(uint32_t signalIdx) { return events_[signalIdx / EVENT_BIT_WIDTH]; }
56	    uint16_t GetMask(uint32_t signalIdx) const { return static_cast<uint16_t>(1u << (signalIdx % EVENT_BIT_WIDTH)); }
57	
58	    // 便捷：直接 Record 一个逻辑信号
59	    CcuResult Record(uint32_t signalIdx)
60	    {
61	        return ccu::EventRecord(events_[signalIdx / EVENT_BIT_WIDTH], GetMask(signalIdx));
62	    }
63	
64	    // ---- Wait 路径 ----
65	
66	    // 等待所有信号
67	    CcuResult WaitAll()
68	    {
69	        for (uint32_t i = 0; i < events_.size(); i++) {
70	            CCU_CHK_RET(ccu::EventWait(events_[i], GetFullMask(i)));
71	        }
72	        return CCU_SUCCESS;
73	    }
74	
75	    // 等待所有信号，跳过指定信号（如本 rank）
76	    CcuResult WaitAllExcept(uint32_t skipIdx)
77	    {
78	        for (uint32_t i = 0; i < events_.size(); i++) {
79	            uint16_t mask = GetFullMask(i);
80	            if (i == skipIdx / EVENT_BIT_WIDTH) {
81	                mask &= ~GetMask(skipIdx);
82	            }
83	            if (mask != 0) {
84	                CCU_CHK_RET(ccu::EventWait(events_[i], mask));
85	            }
86	        }
87	        return CCU_SUCCESS;
88	    }
89	
90	private:
91	    static constexpr uint16_t EVENT_BIT_WIDTH = 16;
92	
93	    uint16_t GetFullMask(uint32_t eventIdx) const
94	    {
95	        if (eventIdx == events_.size() - 1 && signalCount_ % EVENT_BIT_WIDTH != 0) {
96	            return static_cast<uint16_t>((1u << (signalCount_ % EVENT_BIT_WIDTH)) - 1);
97	        }
98	        return static_cast<uint16_t>((1u << EVENT_BIT_WIDTH) - 1);
99	    }
100	
101	    std::vector<ccu::Event> events_;
102	    uint32_t signalCount_ = 0;
103	};
