34	CcuResult AllocGoResource(
35	    LoopGroupConfig& config, LoopGroupResource& res, bool& allocated, uint32_t parallelDim, uint32_t msPerLoop,
36	    uint32_t ckeNum)
37	{
38	    if (allocated) {
39	        return CCU_SUCCESS;
40	    }
41	
42	    config.msInterleave = CCU_MS_INTERLEAVE;
43	    config.loopCount = parallelDim;
44	    config.memSlice = msPerLoop * CCU_MS_SIZE;
45	
46	    // V2算子通过index*ckeNum+offset索引event, 每次loop克隆偏移ckeNum个event, 故需loopCount*ckeNum个event
47	    res.eventCount = config.loopCount * ckeNum;
48	    res.completedEvent = ccu::Array<ccu::Event>(res.eventCount);
49	
50	    res.bufCount = config.loopCount * config.msInterleave;
51	    res.ccuBuf = ccu::Array<ccu::CcuBuffer>(res.bufCount);
52	
53	    allocated = true;
54	    return CCU_SUCCESS;
55	}
