57	std::vector<uint64_t> CalGoSize(uint64_t size, const LoopGroupConfig& config, CcuVersion ccuVersion)
58	{
59	    uint64_t loopSize = config.loopCount * config.memSlice;
60	    uint64_t maxSize = loopSize * (GetMaxLoopIterNum() + 1);
61	
62	    uint64_t m = size / loopSize;
63	    uint64_t n = (size - m * loopSize) / config.memSlice;
64	    uint64_t p = size - m * loopSize - n * config.memSlice;
65	
66	    if (size == maxSize) {
67	        m = GetMaxLoopIterNum();
68	        n = config.loopCount - 1;
69	        p = config.memSlice;
70	    }
71	
72	    HCCL_INFO("Ccu Slice Split: m = %lu, n = %lu, p = %lu", m, n, p);
73	
74	    uint64_t offset = config.memSlice * config.loopCount * m;
75	    uint64_t loopIterNum = m;
76	
77	    uint64_t loopExtendNum = 0;
78	    uint64_t tailSize = 0;
79	    uint64_t LoopNumTwo = 2;
80	    if (n == 0 && p == 0) {
81	        loopExtendNum = 0;
82	        tailSize = 0;
83	    } else if (n != 0 && p == 0) {
84	        loopExtendNum = GetParallelParam(n - 1, 0, 1, ccuVersion);
85	        tailSize = config.memSlice;
86	    } else if (n == 0 && p != 0) {
87	        loopExtendNum = GetParallelParam(0, 0, 1, ccuVersion);
88	        tailSize = p;
89	    } else {
90	        loopExtendNum = GetParallelParam(n - 1, 1, LoopNumTwo, ccuVersion);
91	        tailSize = p;
92	    }
93	
94	    HCCL_INFO(
95	        "[CalGoSize] offset = %lu, loopIterNum = %lu, loopExtendNum = %lu, tailSize = %lu", offset, loopIterNum,
96	        loopExtendNum, tailSize);
97	
98	    return {offset, loopIterNum, loopExtendNum, tailSize};
99	}
