101	CcuResult CreateMultiOpReduceV1(
102	    CcuKernelCtxBase& ctx, GroupReduceVar& var, const size_t channels[], uint32_t channelCount, HcclDataType dataType,
103	    HcclDataType outputDataType, HcclReduceOp opType)
104	{
105	    AllocGoResource(ctx.moConfig, ctx.moRes, ctx.resourceAllocated);
106	
107	    if (ctx.IsLoopEntityRegistered("reduce")) {
108	        return CCU_SUCCESS;
109	    }
110	    ctx.CreateLoopEntity("reduce");
111	    auto& loops = ctx.loopMap["reduce"];
112	
113	    uint32_t channelSize = channelCount;
114	    uint32_t size = channelSize + 1;
115	    uint32_t expansionNum = GetReduceExpansionNum(opType, dataType, outputDataType);
116	    uint32_t usedBufNum = size > expansionNum ? size : expansionNum;
117	    uint32_t loopNum = 2;
118	
119	    for (int32_t index = 0; index < loopNum; index++) {
120	        var.loopRemoteSrc[index].resize(size - 1);
121	
122	        uint32_t bufBase = index * ctx.moConfig.msInterleave;
123	        ccu::Event loopEvt = ctx.moRes.completedEvent[index];
124	
125	        loops.body[index].reset(new ccu::Func([&ctx, index, bufBase, loopEvt, channelSize, size, channels, dataType,
126	                                               outputDataType, opType, &var]() {
127	            for (uint32_t i = 0; i < channelSize; i++) {
128	                ccu::Read(
129	                    channels[i], ctx.moRes.ccuBuf[bufBase + i], var.loopRemoteSrc[index][i], var.loopLen[index],
130	                    loopEvt, 1 << i);
131	            }
132	
133	            ccu::LocalCopy(
134	                ctx.moRes.ccuBuf[bufBase + channelSize], var.loopLocalSrc[index], var.loopLen[index], loopEvt,
135	                1 << channelSize);
136	            ccu::EventWait(loopEvt, (1 << size) - 1);
137	
138	            if (size > 1) {
139	                ccu::LocalReduce(
140	                    &ctx.moRes.ccuBuf[bufBase], size, dataType, outputDataType, opType, var.loopLen[index], loopEvt, 1);
141	                ccu::EventWait(loopEvt);
142	            }
143	
144	            ccu::LocalCopy(var.loopDst[index], ctx.moRes.ccuBuf[bufBase], var.loopLenExp[index], loopEvt, 1);
145	            ccu::EventWait(loopEvt, 1);
146	        }));
147	
148	        loops.loops[index].reset(new ccu::Loop(loops.loopParam[index], *loops.body[index]));
149	    }
150	
151	    return CCU_SUCCESS;
152	}
