224	CcuResult GroupReduceV1(
225	    CcuKernelCtxBase& ctx, const size_t channels[], uint32_t channelCount, ccu::LocalAddr dst,
226	    std::vector<ccu::RemoteAddr> src, ccu::LocalAddr localSrc, GroupOpSizeVars goSize, HcclDataType dataType,
227	    HcclDataType outputDataType, HcclReduceOp opType)
228	{
229	    GroupReduceVar var;
230	    ccu::Variable tmp;
231	    ccu::Variable loopParam;
232	    ccu::Variable sliceSize;
233	    ccu::Variable paraCfg;
234	    ccu::Variable offsetCfg;
235	    ccu::Variable loopCfg0;
236	    ccu::Variable loopCfg1;
237	    CCU_CHK_RET(CreateMultiOpReduceV1(ctx, var, channels, channelCount, dataType, outputDataType, opType));
238	    auto& loops = ctx.loopMap["reduce"];
239	
240	    uint32_t size = channelCount + 1;
241	    uint32_t expansionNum = GetReduceExpansionNum(opType, dataType, outputDataType);
242	    ccu::Variable sliceSizeExpansion;
243	
244	    if (expansionNum != 1) {
245	        tmp = GetExpansionParam(expansionNum);
246	        dst.token = dst.token + tmp;
247	    }
248	
249	    CCU_IF(goSize.addrOffset != 0)
250	    {
251	        loopParam = GetLoopParam(0, ctx.moConfig.memSlice * ctx.moConfig.loopCount, 0);
252	        loopParam = loopParam + goSize.loopParam;
253	        sliceSize = ctx.moConfig.memSlice;
254	        sliceSizeExpansion = ctx.moConfig.memSlice * expansionNum;
255	
256	        for (uint32_t i = 0; i < size - 1; ++i) {
257	            var.loopRemoteSrc[0][i].addr = src[i].addr;
258	            var.loopRemoteSrc[0][i].token = src[i].token;
259	        }
260	        var.loopLocalSrc[0].addr = localSrc.addr;
261	        var.loopLocalSrc[0].token = localSrc.token;
262	        var.loopDst[0].addr = dst.addr;
263	        var.loopDst[0].token = dst.token;
264	        var.loopLen[0] = sliceSize;
265	        var.loopLenExp[0] = sliceSizeExpansion;
266	        paraCfg = GetParallelParam(ctx.moConfig.loopCount - 1, 0, 1, CcuVersion::CCU_V1);
267	        offsetCfg = GetOffsetParam(ctx.moConfig.memSlice, ctx.moConfig.msInterleave, 1);
268	        loops.loopParam[0] = loopParam;
269	        std::vector<ccu::Loop> grpLoops{*loops.loops[0]};
270	        ccu::LoopGroup group(paraCfg, offsetCfg, ctx.moConfig.loopCount, grpLoops);
271	    }
272	
273	    CCU_IF(goSize.parallelParam != 0)
274	    {
275	        for (uint32_t i = 0; i < size - 1; i++) {
276	            src[i].addr += goSize.addrOffset;
277	        }
278	        localSrc.addr += goSize.addrOffset;
279	        for (uint32_t i = 0; i < expansionNum; i++) {
280	            dst.addr += goSize.addrOffset;
281	        }
282	
283	        sliceSizeExpansion = 0;
284	        for (uint32_t i = 0; i < expansionNum; i++) {
285	            sliceSizeExpansion = sliceSizeExpansion + goSize.residual;
286	        }
287	        for (uint32_t i = 0; i < size - 1; ++i) {
288	            var.loopRemoteSrc[0][i].addr = src[i].addr;
289	            var.loopRemoteSrc[0][i].token = src[i].token;
290	        }
291	        var.loopLocalSrc[0].addr = localSrc.addr;
292	        var.loopLocalSrc[0].token = localSrc.token;
293	        var.loopDst[0].addr = dst.addr;
294	        var.loopDst[0].token = dst.token;
295	        var.loopLen[0] = goSize.residual;
296	        var.loopLenExp[0] = sliceSizeExpansion;
297	
298	        for (uint32_t i = 0; i < size - 1; i++) {
299	            src[i].addr += goSize.residual;
300	        }
301	        localSrc.addr += goSize.residual;
302	        for (uint32_t i = 0; i < expansionNum; i++) {
303	            dst.addr += goSize.residual;
304	        }
305	        sliceSize = ctx.moConfig.memSlice;
306	        sliceSizeExpansion = ctx.moConfig.memSlice * expansionNum;
307	
308	        for (uint32_t i = 0; i < size - 1; ++i) {
309	            var.loopRemoteSrc[1][i].addr = src[i].addr;
310	            var.loopRemoteSrc[1][i].token = src[i].token;
311	        }
312	        var.loopLocalSrc[1].addr = localSrc.addr;
313	        var.loopLocalSrc[1].token = localSrc.token;
314	        var.loopDst[1].addr = dst.addr;
315	        var.loopDst[1].token = dst.token;
316	        var.loopLen[1] = sliceSize;
317	        var.loopLenExp[1] = sliceSizeExpansion;
318	        loopCfg0 = GetLoopParam(0, 0, 1);
319	        loopCfg1 = GetLoopParam(0, 0, 1);
320	        offsetCfg = GetOffsetParam(ctx.moConfig.memSlice, ctx.moConfig.msInterleave, 1);
321	        loops.loopParam[0] = loopCfg0;
322	        loops.loopParam[1] = loopCfg1;
323	        std::vector<ccu::Loop> grpLoops{*loops.loops[0], *loops.loops[1]};
324	        ccu::LoopGroup group(goSize.parallelParam, offsetCfg, ctx.moConfig.loopCount, grpLoops);
325	    }
326	    return CCU_SUCCESS;
327	}
