490	        var.loopRemoteDst[index].resize(channelSize);
491	
492	        uint32_t bufBase = index * ctx.moConfig.msInterleave;
493	        ccu::Event loopEvt0 = ctx.moRes.completedEvent[index * CCU_LOOP_CKE_NUM_BCAST_V2 + 0];
494	        ccu::Event loopEvt1 = ctx.moRes.completedEvent[index * CCU_LOOP_CKE_NUM_BCAST_V2 + 1];
495	
496	        loops.body[index].reset(
497	            new ccu::Func([&ctx, index, bufBase, loopEvt0, loopEvt1, channelSize, channels, &var]() {
498	                ccu::LocalCopy(ctx.moRes.ccuBuf[bufBase], var.loopSrc[index], var.loopLen[index], loopEvt0, 1);
499	                ccu::EventWait(loopEvt0, 1);
500	
501	                for (uint32_t i = 0; i < channelSize; i++) {
502	                    ccu::Write(
503	                        channels[i], var.loopRemoteDst[index][i], ctx.moRes.ccuBuf[bufBase], var.loopLen[index],
504	                        loopEvt1, 1 << i);
505	                }
506	
507	                ccu::LocalCopy(
508	                    var.loopLocalDst[index], ctx.moRes.ccuBuf[bufBase], var.loopLen[index], loopEvt1, 1 << channelSize);
509	
510	                ccu::EventWait(loopEvt1, (1 << (channelSize + 1)) - 1);
511	            }));
512	
513	        loops.loops[index].reset(new ccu::Loop(loops.loopParam[index], loops.addrOffset[index], *loops.body[index]));
514	    }
515	    return CCU_SUCCESS;
516	}
