1154	    CcuKernelCtxBase& ctx, GroupLocalReduceVar& var, uint32_t size, HcclDataType dataType, HcclDataType outputDataType,
1155	    HcclReduceOp opType)
1156	{
1157	    AllocGoResource(ctx.moConfig, ctx.moRes, ctx.resourceAllocated, CCU_M2M_LOCAL_COPY_LOOP_COUNT);
1158	
1159	    std::string loopType = "local_reduce";
1160	    if (ctx.IsLoopEntityRegistered(loopType)) {
1161	        return CCU_SUCCESS;
1162	    }
1163	    ctx.CreateLoopEntity(loopType);
1164	    auto& loops = ctx.loopMap[loopType];
1165	
1166	    uint32_t expansionNum = GetReduceExpansionNum(opType, dataType, outputDataType);
1167	    uint32_t loopNum = 2;
1168	    for (int32_t index = 0; index < loopNum; index++) {
1169	        var.loopScratch[index].resize(size);
1170	
1171	        uint32_t bufBase = index * ctx.moConfig.msInterleave;
1172	        ccu::Event loopEvt = ctx.moRes.completedEvent[index];
1173	
1174	        loops.body[index].reset(new ccu::Func([&ctx, index, bufBase, loopEvt, size, dataType, outputDataType, opType,
1175	                                               &var]() {
1176	            for (uint32_t i = 0; i < size; i++) {
1177	                ccu::LocalCopy(
1178	                    ctx.moRes.ccuBuf[bufBase + i], var.loopScratch[index][i], var.loopLen[index], loopEvt, 1 << i);
1179	            }
1180	            ccu::EventWait(loopEvt, (1 << size) - 1);
1181	
1182	            if (size > 1) {
1183	                std::vector<ccu::CcuBuffer> bufs;
1184	                bufs.reserve(size);
1185	                for (uint32_t i = 0; i < size; i++) {
1186	                    bufs.push_back(ctx.moRes.ccuBuf[bufBase + i]);
1187	                }
1188	                ccu::LocalReduce(bufs.data(), size, dataType, outputDataType, opType, var.loopLen[index], loopEvt, 1);
1189	                ccu::EventWait(loopEvt);
1190	            }
1191	
1192	            ccu::LocalCopy(var.loopDst[index], ctx.moRes.ccuBuf[bufBase], var.loopLenExp[index], loopEvt, 1);
1193	            ccu::EventWait(loopEvt, 1);
1194	        }));
1195	
1196	        loops.loops[index].reset(new ccu::Loop(loops.loopParam[index], *loops.body[index]));
1197	    }
1198	
1199	    return CCU_SUCCESS;
1200	}
