1202	CcuResult GroupLocalReduce(
1203	    CcuKernelCtxBase& ctx, ccu::LocalAddr outDstOrg, std::vector<ccu::LocalAddr>& scratchOrg, GroupOpSizeVars goSize,
1204	    HcclDataType dataType, HcclDataType outputDataType, HcclReduceOp opType)
1205	{
1206	    const uint32_t size = scratchOrg.size();
1207	
1208	    GroupLocalReduceVar var;
1209	    ccu::Variable tmp;
1210	    ccu::Variable loopParam;
1211	    ccu::Variable sliceSize;
1212	    ccu::Variable paraCfg;
1213	    ccu::Variable offsetCfg;
1214	    ccu::Variable loopCfg0;
1215	    ccu::Variable loopCfg1;
1216	    CCU_CHK_RET(CreateReduceLoop(ctx, var, size, dataType, outputDataType, opType));
1217	    auto& loops = ctx.loopMap["local_reduce"];
1218	
1219	    uint32_t expansionNum = GetReduceExpansionNum(opType, dataType, outputDataType);
1220	    ccu::Variable sliceSizeExpansion;
1221	
1222	    ccu::LocalAddr dst = outDstOrg;
1223	    if (expansionNum != 1) {
1224	        tmp = GetExpansionParam(expansionNum);
1225	        dst.token = dst.token + tmp;
1226	    }
1227	
1228	    CCU_IF(goSize.loopParam != 0)
1229	    {
1230	        loopParam = GetLoopParam(0, ctx.moConfig.memSlice * ctx.moConfig.loopCount, 0);
1231	        loopParam += goSize.loopParam;
1232	        sliceSize = ctx.moConfig.memSlice;
1233	        sliceSizeExpansion = ctx.moConfig.memSlice * expansionNum;
1234	
1235	        for (uint32_t i = 0; i < size; ++i) {
1236	            var.loopScratch[0][i].addr = scratchOrg[i].addr;
1237	            var.loopScratch[0][i].token = scratchOrg[i].token;
1238	        }
1239	        var.loopDst[0].addr = dst.addr;
1240	        var.loopDst[0].token = dst.token;
1241	        var.loopLen[0] = sliceSize;
1242	        var.loopLenExp[0] = sliceSizeExpansion;
1243	        paraCfg = GetParallelParam(ctx.moConfig.loopCount - 1, 0, 1);
1244	        offsetCfg = GetOffsetParam(ctx.moConfig.memSlice, ctx.moConfig.msInterleave, 1);
1245	
1246	        loops.loopParam[0] = loopParam;
1247	        std::vector<ccu::Loop> grpLoops{*loops.loops[0]};
1248	        ccu::LoopGroup group(paraCfg, offsetCfg, ctx.moConfig.loopCount, grpLoops);
1249	    }
1250	
1251	    CCU_IF(goSize.parallelParam != 0)
1252	    {
1253	        for (uint32_t i = 0; i < size; i++) {
1254	            scratchOrg[i].addr += goSize.addrOffset;
1255	        }
1256	
1257	        for (uint32_t i = 0; i < expansionNum; i++) {
1258	            dst.addr += goSize.addrOffset;
1259	        }
1260	
1261	        sliceSizeExpansion = 0;
1262	        for (uint32_t i = 0; i < expansionNum; i++) {
1263	            sliceSizeExpansion += goSize.residual;
1264	        }
1265	
1266	        for (uint32_t i = 0; i < size; ++i) {
1267	            var.loopScratch[0][i].addr = scratchOrg[i].addr;
1268	            var.loopScratch[0][i].token = scratchOrg[i].token;
1269	        }
1270	        var.loopDst[0].addr = dst.addr;
1271	        var.loopDst[0].token = dst.token;
1272	        var.loopLen[0] = goSize.residual;
1273	        var.loopLenExp[0] = sliceSizeExpansion;
1274	
1275	        for (uint32_t i = 0; i < size; i++) {
1276	            scratchOrg[i].addr += goSize.residual;
1277	        }
1278	
1279	        for (uint32_t i = 0; i < expansionNum; i++) {
1280	            dst.addr += goSize.residual;
1281	        }
1282	        sliceSize = ctx.moConfig.memSlice;
1283	        sliceSizeExpansion = ctx.moConfig.memSlice * expansionNum;
1284	
1285	        for (uint32_t i = 0; i < size; ++i) {
1286	            var.loopScratch[1][i].addr = scratchOrg[i].addr;
1287	            var.loopScratch[1][i].token = scratchOrg[i].token;
1288	        }
1289	        var.loopDst[1].addr = dst.addr;
1290	        var.loopDst[1].token = dst.token;
1291	        var.loopLen[1] = sliceSize;
1292	        var.loopLenExp[1] = sliceSizeExpansion;
1293	        loopCfg0 = GetLoopParam(0, 0, 1);
1294	        loopCfg1 = GetLoopParam(0, 0, 1);
1295	        offsetCfg = GetOffsetParam(ctx.moConfig.memSlice, ctx.moConfig.msInterleave, 1);
1296	
1297	        loops.loopParam[0] = loopCfg0;
1298	        loops.loopParam[1] = loopCfg1;
1299	        std::vector<ccu::Loop> grpLoops{*loops.loops[0], *loops.loops[1]};
1300	        ccu::LoopGroup group(goSize.parallelParam, offsetCfg, ctx.moConfig.loopCount, grpLoops);
1301	    }
1302	    return CCU_SUCCESS;
1303	}
