63	HcclResult CcuTempAllReduceMesh1D::CalcSliceInfo(const u64 dataSize, RankSliceInfo& sliceInfoVec)
64	{
65	    CHK_PRT_RET(
66	        templateRankSize_ == 0, HCCL_ERROR("[CcuTempAllReduceMesh1D] templateRankSize_ is 0"),
67	        HcclResult::HCCL_E_INTERNAL);
68	    std::vector<SliceInfo> tmp(subCommRanks_.size());
69	    sliceInfoVec.resize(templateRankSize_, tmp);
70	
71	    u64 unitAllignSize = DataTypeSizeGet(dataType_);
72	    u64 chunkSize = RoundUp(dataSize, (templateRankSize_ * unitAllignSize)) * unitAllignSize;
73	    HCCL_INFO(
74	        "chunkSize[%llu], dataSize[%llu], templateRankSize_[%u], unitAllignSize[%llu]", chunkSize, dataSize,
75	        templateRankSize_, unitAllignSize);
76	    u64 accumOff = 0;
77	    for (u32 rankIdx = 0; rankIdx < templateRankSize_; rankIdx++) {
78	        u64 currChunkSize = ((dataSize - accumOff) > chunkSize) ? chunkSize : (dataSize - accumOff);
79	        SliceInfo slice = {accumOff, currChunkSize};
80	        sliceInfoVec[rankIdx][0] = slice;
81	        accumOff += currChunkSize;
82	    }
83	
84	    CHK_PRT_RET(
85	        (sliceInfoVec[templateRankSize_ - 1][0].offset + sliceInfoVec[templateRankSize_ - 1][0].size != dataSize),
86	        HCCL_ERROR(
87	            "[CcuTempAllReduceMesh1D] chunkSize:[%llu], Rank:[%d], SliceInfo calculation error!", chunkSize, myRank_),
88	        HcclResult::HCCL_E_INTERNAL);
89	    return HcclResult::HCCL_SUCCESS;
90	}
