92	HcclResult CcuTempAllReduceMesh1D::CalcRes(
93	    HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
94	    AlgResourceRequest& resourceRequest)
95	{
96	    // 不需要从流
97	    resourceRequest.notifyNumOnMainThread = 0;
98	    resourceRequest.slaveThreadNum = 0;
99	    // 多少个kernel
100	    resourceRequest.ccuKernelNum.push_back(1);
101	    HCCL_DEBUG(
102	        "[CcuTempAllReduceMesh1D::CalcRes] notifyNumOnMainThread[%u] slaveThreadNum[%u]",
103	        resourceRequest.notifyNumOnMainThread, resourceRequest.slaveThreadNum);
104	
105	    // 创建每个kernel的ctxArg，放入kernelInfo, 然后将kernelinfo放入resourceRequest.ccuKernelInfos
106	    CcuKernelInfo kernelInfo;
107	    CHK_SAFETY_FUNC_RET(
108	        strcpy_s(kernelInfo.kernelFuncName, sizeof(kernelInfo.kernelFuncName), "CcuKernelAllReduceMesh1D"));
109	    kernelInfo.kernelFunc = reinterpret_cast<void*>(CcuAllReduceMesh1DKernel);
110	
111	    std::vector<HcclChannelDesc> channelDescs;
112	    if (topoInfo->level0Topo != Level0Shape::MESH_1D_CLOS) {
113	        CHK_RET(CalcChannelRequestMesh1D(comm, param, topoInfo, subCommRanks_, channelDescs));
114	    } else {
115	        std::vector<HcclChannelDesc> myChannelDescs;
116	        CHK_RET(CalcChannelRequestMesh1DWithPriorityTopo(
117	            comm, param, topoInfo, subCommRanks_, myChannelDescs, CommTopo::COMM_TOPO_1DMESH));
118	        for (auto channel : myChannelDescs) {
119	            if (channel.channelProtocol == COMM_PROTOCOL_UBC_CTP) {
120	                channelDescs.push_back(channel);
121	            }
122	        }
123	        HCCL_DEBUG("[CcuTempAllReduceMesh1D::CalcRes] Get Mesh Channel Success!");
124	    }
125	    auto kernelArg = std::make_shared<CcuKernelArgAllReduceMesh1D>();
126	    kernelArg->rankSize = templateRankSize_;
127	    kernelArg->rankId = mySubCommRank_;
128	    kernelArg->opParam = param;
129	    kernelArg->subCommRanks = subCommRanks_;
130	    kernelInfo.setKernelArg(kernelArg);
131	    kernelInfo.channels = channelDescs;
132	    resourceRequest.ccuKernelInfos.push_back(kernelInfo);
133	
134	    HCCL_DEBUG(
135	        "[CcuTempAllReduceMesh1D::CalcRes] channelDescs.size()=%llu, templateRankSize_=%llu, "
136	        "ccuKernelInfos.size()=%llu",
137	        channelDescs.size(), templateRankSize_, resourceRequest.ccuKernelInfos.size());
138	    return HcclResult::HCCL_SUCCESS;
139	}
140	
141	/* CCU数据类型校验规则
142	 * Reduce算子：
143	 *      高精度模式，当dataType==outputDataType时，可选类型为FP32、FP16、BF16、UINT8、INT16、INT32；
144	 *      低精度模式，当dataType!=outputDataType时，dataType可选范围HIF8、E4M3、E5M2、INT8；outputDataType可选范围FP32、FP16、BF16；
145	 * 非Reduce算子：任意数据类型，dataType==outputDataType即可。
146	 */
147	HcclResult CcuTempAllReduceMesh1D::CheckCcuDataType() const
148	{
149	    if (dataType_ == outputDataType_) {
150	        // allreduce算子高精度模式
151	        HCCL_INFO("HIGH PRECISION");
152	        std::set<HcclDataType> highPrecisionSupportedInputDataType = {
153	            HcclDataType::HCCL_DATA_TYPE_FP32,  HcclDataType::HCCL_DATA_TYPE_FP16,  HcclDataType::HCCL_DATA_TYPE_BFP16,
154	            HcclDataType::HCCL_DATA_TYPE_UINT8, HcclDataType::HCCL_DATA_TYPE_INT16, HcclDataType::HCCL_DATA_TYPE_INT32};
155	        if (highPrecisionSupportedInputDataType.count(dataType_) == 0) {
156	            HCCL_ERROR("Unsupported HcclDataType [%d] For OpType [%d].", dataType_, opType_);
157	            return HcclResult::HCCL_E_PARA;
158	        }
159	    } else if (outputDataType_ != HcclDataType::HCCL_DATA_TYPE_RESERVED) {
160	        // allreduce算子低精度模式
161	        HCCL_INFO("LOW PRECISION");
162	        HCCL_ERROR("Unsupported LOW PRECISION, Output HcclDataType [%d] For OpType [%d].", outputDataType_, opType_);
163	        return HcclResult::HCCL_E_PARA;
164	    }
165	    HCCL_INFO("CheckCcuDataType Success!");
166	    return HcclResult::HCCL_SUCCESS;
167	}
168	
169	HcclResult CcuTempAllReduceMesh1D::KernelRun(
170	    const OpParam& param, const TemplateDataParams& templateDataParams, TemplateResource& templateResource)
171	{
172	    if (outputDataType_ == HcclDataType::HCCL_DATA_TYPE_RESERVED) {
173	        outputDataType_ = dataType_;
174	    }
175	    CHK_RET(CheckCcuDataType());
176	    buffInfo_ = templateDataParams.buffInfo;
177	    RankSliceInfo sliceInfoVec;
178	    CHK_RET(CalcSliceInfo(templateDataParams.sliceSize, sliceInfoVec));
179	
180	    uint64_t inputAddr = PointerToAddr(buffInfo_.inputPtr) + buffInfo_.inBuffBaseOff;
181	    uint64_t outputAddr = PointerToAddr(buffInfo_.outputPtr) + buffInfo_.outBuffBaseOff;
182	    uint64_t token;
183	    CHK_RET(GetToken(buffInfo_, token));
184	
185	    uint64_t sliceSize = sliceInfoVec[myRank_][0].size; // 获取本rank需要处理的数据量
186	    uint64_t offSet = sliceInfoVec[myRank_][0].offset;  // 自己需要 reduce 的数据基于 inputAddr 的偏移
187	    LoopGroupConfig config{};
188	    config.msInterleave = CCU_MS_INTERLEAVE;
189	    config.loopCount = CCU_MS_DEFAULT_LOOP_COUNT;
190	    config.memSlice = CCU_MS_SIZE;
191	    auto goSize = CalGoSize(sliceSize, config, GetCcuVersion());
192	
193	    std::vector<uint64_t> taskArgs = {inputAddr, outputAddr, token, offSet, goSize[0], goSize[1], goSize[2], goSize[3]};
194	    uint64_t argSize = 8;
195	
196	    HCCL_INFO(
197	        "[CcuTempAllReduceMesh1D] inputAddr[%llu], outputAddr[%llu], sliceSize[%llu], offSet[%llu]", inputAddr,
198	        outputAddr, sliceSize, offSet);
199	
200	    CcuResult launchRet
201	        = HcommCcuKernelLaunch(templateResource.threads[0], templateResource.ccuKernels[0], taskArgs.data(), argSize);
202	    if (launchRet != CCU_SUCCESS) {
203	        HCCL_ERROR("[CcuTempAllReduceMesh1D::KernelRun] kernel launch failed, ccuRet -> %d", launchRet);
204	        return ConvertCcuToHccl(launchRet);
205	    }
206	    CcuKernelSubmitInfo submitInfo;
207	    submitInfo.kernelHandle = templateResource.ccuKernels[0];
208	    CHK_RET(FillCachedArgs(
209	        submitInfo, inputAddr, outputAddr, token, offSet, goSize[0], goSize[1], goSize[2], goSize[3],
210	        buffInfo_.inBuffBaseOff, buffInfo_.outBuffBaseOff));
211	    templateResource.submitInfos.push_back(submitInfo);
212	
213	    return HcclResult::HCCL_SUCCESS;
214	}
215	
216	HcclResult CcuTempAllReduceMesh1D::FastLaunch(const OpParam& param, const TemplateFastLaunchCtx& tempFastLaunchCtx)
217	{
218	    if (tempFastLaunchCtx.ccuKernelSubmitInfos.size() == 0) {
219	        HCCL_INFO("[CcuTempAllReduceMesh1D::FastLaunch] ccu kernel num is 0, just success.");
220	        return HCCL_SUCCESS;
221	    }
222	    HCCL_DEBUG("[CcuTempAllReduceMesh1D::FastLaunch] start");
223	    uint64_t* args = const_cast<uint64_t*>(tempFastLaunchCtx.ccuKernelSubmitInfos[0].cachedArgs);
224	    constexpr u32 inputIdx = 0;
225	    constexpr u32 outputIdx = 1;
226	    constexpr u32 inputOffsetIdx = 8;
227	    constexpr u32 outputOffsetIdx = 9;
228	    uint64_t argSize = 8;
229	
230	    args[inputIdx] = PointerToAddr(tempFastLaunchCtx.buffInfo.inputPtr) + args[inputOffsetIdx];
231	    args[outputIdx] = PointerToAddr(tempFastLaunchCtx.buffInfo.outputPtr) + args[outputOffsetIdx];
232	
233	    void* taskArgs = reinterpret_cast<void*>(args);
234	    CcuResult launchRet = HcommCcuKernelLaunch(
235	        tempFastLaunchCtx.threads[0], tempFastLaunchCtx.ccuKernelSubmitInfos[0].kernelHandle, taskArgs, argSize);
236	    if (launchRet != CCU_SUCCESS) {
237	        HCCL_ERROR("[CcuTempAllReduceMesh1D::FastLaunch] kernel launch failed, ccuRet -> %d", launchRet);
238	        return ConvertCcuToHccl(launchRet);
239	    }
240	
241	    HCCL_DEBUG("[CcuTempAllReduceMesh1D::FastLaunch] end");
242	    return HcclResult::HCCL_SUCCESS;
243	}
244	
245	u64 CcuTempAllReduceMesh1D::GetThreadNum() const { return 1; }
246	} // namespace ops_hccl
