29	    // ==================== 类型别名 ====================
30	    using LoopConfig = ::CcuLoopConfig;
31	    using LoopGroupConfig = ::CcuLoopGroupConfig;
32	
33	    // ==================== 资源创建 ====================
34	
35	    template <typename T>
36	    inline T GetResByChannel(ChannelHandle /*channel*/, uint32_t /*index*/)
37	    {
38	        static_assert(
39	            sizeof(T) == 0, "ccu::GetResByChannel<T> is not specialized for this type T; "
40	                            "currently supported: Variable.");
41	    }
42	    template <>
43	    inline Variable GetResByChannel<Variable>(ChannelHandle channel, uint32_t varIndex)
44	    {
45	        Variable v{detail::NoAllocTag{}};
46	        CCU_THROW_IF_FAILED(
47	            CcuVariableCreateByChannel(channel, varIndex, &v.handle), "CcuVariableCreateByChannel: failed");
48	        return v;
49	    }
50	
51	    // ==================== 事件 ====================
52	    // mask 由调用方独立传入（与 Event 句柄解耦），ccu::SetMask 已废弃删除。
53	    // 默认 mask = 1，对原有"未显式设 mask"的调用保持二进制兼容语义。
54	    inline CcuResult EventRecord(Event e, uint16_t mask = 1) { return CcuEventRecord(e.handle, mask); }
55	    inline CcuResult EventWait(Event e, uint16_t mask = 1) { return CcuEventWait(e.handle, mask); }
56	    // 同卡内跨 core 通知：直接以 notifyTag 字符串作为生产者/消费者配对标识
57	    inline CcuResult EventRecord(const char* notifyTag, uint16_t mask = 1)
58	    {
59	        return CcuLocalNotifyRecord(notifyTag, mask);
60	    }
61	    inline CcuResult EventWait(const char* notifyTag, uint16_t mask = 1) { return CcuLocalNotifyWait(notifyTag, mask); }
62	    inline CcuResult NotifyRecord(ChannelHandle channel, uint32_t remoteNotifyIdx, uint16_t mask = 1)
63	    {
64	        return CcuNotifyRecord(channel, remoteNotifyIdx, mask);
65	    }
66	    inline CcuResult NotifyWait(ChannelHandle channel, uint32_t localNotifyIdx, uint16_t mask = 1)
67	    {
68	        return CcuNotifyWait(channel, localNotifyIdx, mask);
69	    }
70	    inline CcuResult WriteVariableWithNotify(
71	        ChannelHandle channel, Variable var, uint32_t remoteVarIdx, uint32_t remoteNotifyIdx, uint16_t mask = 1)
72	    {
73	        return CcuWriteVariableWithNotify(channel, var.handle, remoteVarIdx, remoteNotifyIdx, mask);
74	    }
75	
76	    // ==================== 加载 ====================
77	    inline CcuResult LoadArg(Variable v, uint32_t argId) { return CcuLoadArg(v.handle, argId); }
78	    inline CcuResult Load(uint64_t addr, Array<Variable>& vArr, uint32_t num)
79	    {
80	        return CcuLoadVar(addr, vArr[0].handle, num);
81	    }
82	    inline CcuResult Load(uint64_t addr, Variable v) { return CcuLoadVar(addr, v.handle, 1); }
83	    inline CcuResult Load(Variable addrVar, Array<Variable>& vArr, uint32_t num)
84	    {
85	        return CcuLoadVarFromVarAddr(addrVar.handle, vArr[0].handle, num);
86	    }
87	    inline CcuResult Load(Variable addrVar, Variable v) { return CcuLoadVarFromVarAddr(addrVar.handle, v.handle, 1); }
88	    inline CcuResult Store(uint64_t addr, Array<Variable>& vArr, uint32_t num)
89	    {
90	        return CcuStoreVar(addr, vArr[0].handle, num);
91	    }
92	    inline CcuResult Store(uint64_t addr, Variable v) { return CcuStoreVar(addr, v.handle, 1); }
93	    inline CcuResult Store(Variable addrVar, Array<Variable>& vArr, uint32_t num)
94	    {
95	        return CcuStoreVarToVarAddr(addrVar.handle, vArr[0].handle, num);
96	    }
97	    inline CcuResult Store(Variable addrVar, Variable v) { return CcuStoreVarToVarAddr(addrVar.handle, v.handle, 1); }
98	    // ==================== 本地拷贝（3 种重载） ====================
99	    // 各数据 API 末尾统一新增 uint16_t mask = 1，与 Event 句柄解耦。
100	
101	    // LocalAddr → LocalAddr,LocalAddr → CcuBuffer,CcuBuffer → LocalAddr
102	    inline CcuResult LocalCopy(LocalAddr dst, LocalAddr src, Variable len, Event event, uint16_t mask = 1)
103	    {
104	        return CcuLocalCopyMemToMem(dst.handle, src.handle, len.handle, event.handle, mask);
105	    }
106	    inline CcuResult LocalCopy(CcuBuffer dst, LocalAddr src, Variable len, Event event, uint16_t mask = 1)
107	    {
108	        return CcuLocalCopyMemToBuffer(dst.handle, src.handle, len.handle, event.handle, mask);
109	    }
110	    inline CcuResult LocalCopy(LocalAddr dst, CcuBuffer src, Variable len, Event event, uint16_t mask = 1)
111	    {
112	        return CcuLocalCopyBufferToMem(dst.handle, src.handle, len.handle, event.handle, mask);
113	    }
114	
115	    // ==================== 本地 Reduce ====================
116	    inline CcuResult LocalReduce(
117	        LocalAddr dst, LocalAddr src, Variable len, HcclDataType dataType, HcclReduceOp opType, Event event,
118	        uint16_t mask = 1)
119	    {
120	        return CcuLocalMemReduce(dst.handle, src.handle, len.handle, dataType, opType, event.handle, mask);
121	    }
122	    inline CcuResult LocalReduce(
123	        CcuBuffer* buffers, uint32_t count, HcclDataType dataType, HcclDataType outputDataType, HcclReduceOp opType,
124	        Variable len, Event event, uint16_t mask = 1)
125	    {
126	        if (buffers == nullptr || count == 0) {
127	            return CcuResult::CCU_E_PARA;
128	        }
129	        CcuBufferHandle bufHandles[count];
130	        for (uint32_t i = 0; i < count; i++) {
131	            bufHandles[i] = buffers[i].handle;
132	        }
133	        return CcuLocalBufferReduce(
134	            bufHandles, count, dataType, outputDataType, opType, len.handle, event.handle, mask);
135	    }
136	
137	    // ==================== 远端读====================
138	
139	    // 远端读 LocalAddr ← RemoteAddr
140	    inline CcuResult
141	    Read(ChannelHandle ch, LocalAddr local, RemoteAddr remote, Variable len, Event event, uint16_t mask = 1)
142	    {
143	        return CcuReadMemToMem(ch, local.handle, remote.handle, len.handle, event.handle, mask);
144	    }
145	    // 远端读 CcuBuffer ← RemoteAddr
146	    inline CcuResult
147	    Read(ChannelHandle ch, CcuBuffer local, RemoteAddr remote, Variable len, Event event, uint16_t mask = 1)
148	    {
149	        return CcuReadMemToBuffer(ch, local.handle, remote.handle, len.handle, event.handle, mask);
150	    }
151	    // 远端读 LocalAddr ← RemoteAddr Reduce (Reduce)
152	    inline CcuResult ReadReduce(
153	        ChannelHandle ch, LocalAddr local, RemoteAddr remote, Variable len, HcclDataType dataType, HcclReduceOp opType,
154	        Event event, uint16_t mask = 1)
155	    {
156	        return CcuReadMemToMemReduce(ch, local.handle, remote.handle, len.handle, dataType, opType, event.handle, mask);
157	    }
158	
159	    // ==================== 远端写 ====================
160	
161	    // LocalAddr → RemoteAddr
162	    inline CcuResult
163	    Write(ChannelHandle ch, RemoteAddr remote, LocalAddr local, Variable len, Event event, uint16_t mask = 1)
164	    {
165	        return CcuWriteMemToMem(ch, remote.handle, local.handle, len.handle, event.handle, mask);
166	    }
167	    // CcuBuffer → RemoteAddr
168	    inline CcuResult
169	    Write(ChannelHandle ch, RemoteAddr remote, CcuBuffer local, Variable len, Event event, uint16_t mask = 1)
170	    {
171	        return CcuWriteBufferToMem(ch, remote.handle, local.handle, len.handle, event.handle, mask);
172	    }
173	    // LocalAddr → RemoteAddr Reduce (Reduce)
174	    inline CcuResult WriteReduce(
175	        ChannelHandle ch, RemoteAddr remote, LocalAddr local, Variable len, HcclDataType dataType, HcclReduceOp opType,
176	        Event event, uint16_t mask = 1)
177	    {
178	        return CcuWriteMemToMemReduce(
179	            ch, remote.handle, local.handle, len.handle, dataType, opType, event.handle, mask);
180	    }
181	
182	} // namespace ccu
183	} // namespace AscendC
184	
185	#endif // CCU_PRIMITIVES_DL_HPP
